#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[])
{
    /* If no argument is supplied, treat the input as an empty string. */
    if (argc <= 1) {
        puts("PALINDROME");
        return 0;
    }

    const char *input = argv[1];
    size_t len = strlen(input);

    /* The original program rejects inputs longer than 1024 characters. */
    if (len > 1024) {
        puts("TOO_LONG");
        return 0;
    }

    /* Build a normalized version of the string: keep only alphanumeric
       characters and convert letters to lower case. */
    char norm[1025];
    size_t n = 0;
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            norm[n++] = (char)tolower(c);
        }
    }
    norm[n] = '\0';

    /* Check whether the normalized string is a palindrome. */
    int is_pal = 1;
    for (size_t i = 0; i < n / 2; ++i) {
        if (norm[i] != norm[n - 1 - i]) {
            is_pal = 0;
            break;
        }
    }

    puts(is_pal ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
